using Auth.Application.DTOs;
using Auth.Domain.Enums;
using ErrorOr;
using MediatR;

namespace Auth.Application.Features.MachineKeys.CreateMachineKey;

/// <summary>
/// Gives an application a new machine key (OI-128): generated by the server, or the public key the
/// administrator pasted.
/// </summary>
/// <param name="ApplicationId">The application the key will authenticate.</param>
/// <param name="Name">An optional label.</param>
/// <param name="PublicKeyJwk">
/// A public P-256 JWK of the team's own; null or empty to have the server generate the pair and
/// return the private key once.
/// </param>
/// <param name="PublicBaseUrl">The API's public origin, for the token endpoint the answer names.</param>
/// <param name="Purpose">
/// What the key authenticates (OI-171): a machine key for <c>client_credentials</c> (the default), or
/// a sign-in key for a server-side application's <c>authorization_code</c> and <c>refresh_token</c>.
/// </param>
public record CreateMachineKeyCommand(
    Guid ApplicationId,
    string? Name,
    string? PublicKeyJwk,
    string PublicBaseUrl,
    MachineKeyPurpose Purpose = MachineKeyPurpose.Machine) : IRequest<ErrorOr<CreateMachineKeyResponse>>
{
    /// <summary>The administrator creating the key.</summary>
    public Guid CreatedBy { get; init; }
}
